const stream = useAgentStream({
  api: "/api/chat",
  map: (message) => {
    if (message.data === "[DONE]") return { type: "done" };
    const delta = JSON.parse(message.data).choices[0]?.delta?.content;
    return delta ? { type: "text", delta } : null;
  },
});
